// ValidateStartRequestBody runs the validations defined on StartRequestBody
func ValidateStartRequestBody(body *StartRequestBody) (err error) {
	if body.TargetID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("target_id", "body"))
	}
	if body.TargetManifestSha256 == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("target_manifest_sha256", "body"))
	}
	if body.ExpectedVMUID == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("expected_vm_uid", "body"))
	}
	if body.ExpectedRevocationEpoch == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("expected_revocation_epoch", "body"))
	}
	if body.ExpectedInstalledInventorySha256 == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("expected_installed_inventory_sha256", "body"))
	}
	if body.IdempotencyKey == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("idempotency_key", "body"))
	}
	if body.AllowReboot == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("allow_reboot", "body"))
	}
	if body.TargetID != nil {
		err = goa.MergeErrors(err, goa.ValidatePattern("body.target_id", *body.TargetID, "^[a-z0-9][a-z0-9._-]{0,127}$"))
	}
	if body.TargetManifestSha256 != nil {
		err = goa.MergeErrors(err, goa.ValidatePattern("body.target_manifest_sha256", *body.TargetManifestSha256, "^[0-9a-f]{64}$"))
	}
	if body.ExpectedVMUID != nil {
		err = goa.MergeErrors(err, goa.ValidatePattern("body.expected_vm_uid", *body.ExpectedVMUID, "^[A-Za-z0-9][A-Za-z0-9._-]{0,255}$"))
	}
	if body.ExpectedInstalledInventorySha256 != nil {
		err = goa.MergeErrors(err, goa.ValidatePattern("body.expected_installed_inventory_sha256", *body.ExpectedInstalledInventorySha256, "^[0-9a-f]{64}$"))
	}
	if body.IdempotencyKey != nil {
		err = goa.MergeErrors(err, goa.ValidatePattern("body.idempotency_key", *body.IdempotencyKey, "^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$"))
	}
	return
}
